//! Genuine public all12 CHECK observations; no generator writes/oracle claim.
#[path="../../../shared/test_scratch.rs"]mod scratch;
use dmbc::{runner_host::BuildHost,request::{BuildRequest,Command},policy_request::{PolicyInputRequest,WorkspacePolicyRequest,AnalysisContext},GeneratorName};
use std::{fs,io,path::{Path,PathBuf},collections::BTreeMap,error::Error};
#[global_allocator]static ALLOC:mimalloc::MiMalloc=mimalloc::MiMalloc;
fn fixture(label:&str,missing:bool)->(PathBuf,PathBuf,BuildRequest){
 let outer=scratch::dir(label);let root=outer.join("source");let cache=outer.join("cache");fs::create_dir_all(root.join("code/engine/_generated")).unwrap();fs::create_dir_all(root.join("tools/ci")).unwrap();fs::create_dir_all(root.join("tgui/packages/tgui/interfaces")).unwrap();fs::create_dir_all(&cache).unwrap();fs::write(root.join("code/probe.dm"),"/obj/box\n    var/count\n    proc/probe()\n        return count\n").unwrap();fs::write(root.join("tools/ci/lint_scopes.toml"),"").unwrap();if !missing{fs::write(root.join("deepquarry.dme"),"#include \"code/probe.dm\"\n").unwrap();}
 let root=fs::canonicalize(root).unwrap();let Command::Build(request)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("actual request parser")};let mut request=*request;request.workers=1;request.no_cache=true;request.exact_inputs=true;request.progress_enabled=false;request.engine_template=None;request.bootstrap_catalog=false;request.timeout_seconds=Some(60);request.cache_root=Some(cache.clone());request.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.clone(),recursive_roots:vec![root.join("code")],configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_generators:vec![GeneratorName::Actions,GeneratorName::AutoTracked,GeneratorName::Declare,GeneratorName::DeclareIds,GeneratorName::Deps,GeneratorName::DerivedReads,GeneratorName::Plans,GeneratorName::Reads,GeneratorName::Stats,GeneratorName::SystemAccessors,GeneratorName::TrackedLists,GeneratorName::UiTypes],..Default::default()});(root,cache,request)
}
fn actual_fixture_files(root:&Path)->BTreeMap<PathBuf,Vec<u8>>{fn visit(root:&Path,at:&Path,out:&mut BTreeMap<PathBuf,Vec<u8>>){for e in fs::read_dir(at).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){visit(root,&e.path(),out)}else{out.insert(e.path().strip_prefix(root).unwrap().to_owned(),fs::read(e.path()).unwrap());}}}let mut out=BTreeMap::new();visit(root,root,&mut out);out}
fn actual_io<'a>(mut error:&'a(dyn Error+'static))->Option<&'a io::Error>{loop{if let Some(actual)=error.downcast_ref::<io::Error>(){return Some(actual)}error=error.source()?;}}
#[test]fn actual_all12_generation_check_observation_exports_actual_phase_journals_targets_and_final_report_without_writes(){
 let(root,_cache,request)=fixture("all12-observation-real",false);let before=actual_fixture_files(&root);let mut host=BuildHost::default();let mut calls=0;let clean=dmbc::with_all_generation_check_input_observation(&mut host,request,|mut observation|{
  calls+=1;let mut header=Vec::new();observation.write_header(&mut header)?;let header:serde_json::Value=serde_json::from_slice(&header).map_err(io::Error::other)?;assert_eq!(header["check_only"],true);assert_eq!(header["full_generation_parity"],false);let slots=observation.phase_slots();assert!(slots[1]&&slots[2]);let mut final_names=std::collections::BTreeSet::new();
  for slot in 0..3{if !slots[slot]{continue}let(mut inputs,mut targets,mut journal)=(Vec::new(),Vec::new(),Vec::new());observation.write_phase(slot,&mut inputs,&mut targets,&mut journal)?;let _:dmbc::input_snapshot::InputSnapshot=serde_json::from_slice(&inputs).map_err(io::Error::other)?;let target:serde_json::Value=serde_json::from_slice(&targets).map_err(io::Error::other)?;assert!(target.as_array().unwrap().iter().all(|row|row["previous"].is_null()));assert_eq!(&journal[..8],b"DQGENJ01");assert_eq!(u64::from_le_bytes(journal[16..24].try_into().unwrap()),journal.len()as u64);assert_eq!(u128::from_le_bytes(journal[24..40].try_into().unwrap()),xxhash_rust::xxh3::xxh3_128(&journal[40..]));let phase=&header["phases"][slot];assert_eq!(phase["journal_length"].as_u64(),Some(journal.len()as u64));if slot!=0{for name in phase["names"].as_array().unwrap().iter().filter_map(|name|name.as_str()){assert!(final_names.insert(name.to_owned()),"no duplicated final production role");}}
  }assert_eq!(final_names.len(),12);assert_eq!(final_names,header["requested_names"].as_array().unwrap().iter().map(|name|name.as_str().unwrap().to_owned()).collect());let mut report=Vec::new();observation.write_report(&mut report)?;let report:serde_json::Value=serde_json::from_slice(&report).map_err(io::Error::other)?;assert_eq!(report["schema"],"native-generation-v1");assert_eq!(report["committed"],false);assert!(report["changed"].as_array().unwrap().is_empty());Ok(())
 }).unwrap();assert_eq!(calls,1);assert!(!clean,"all ordinary generated destinations were genuinely absent");assert_eq!(actual_fixture_files(&root),before);
}
#[test]fn actual_all12_generation_check_observation_uses_real_missing_dme_subject_without_creating_manifest(){
 let(root,_cache,request)=fixture("all12-observation-missing",true);let before=actual_fixture_files(&root);let mut host=BuildHost::default();let mut calls=0;dmbc::with_all_generation_check_input_observation(&mut host,request,|observation|{calls+=1;assert!(observation.phase_slots()[1]);assert!(observation.phase_slots()[2]);Ok(())}).unwrap();assert_eq!(calls,1);assert!(!root.join("deepquarry.dme").exists());assert_eq!(actual_fixture_files(&root),before);
}
#[test]fn actual_all12_generation_check_observation_first_callback_io_is_primary_and_same_host_recovers(){
 let(root,_cache,request)=fixture("all12-observation-first-io",false);let before=actual_fixture_files(&root);let mut host=BuildHost::default();let error=dmbc::with_all_generation_check_input_observation(&mut host,request.clone(),|_|Err(io::Error::from_raw_os_error(1450))).unwrap_err();assert_eq!(actual_io(error.as_ref()).unwrap().raw_os_error(),Some(1450));assert_eq!(actual_fixture_files(&root),before);dmbc::with_all_generation_check_input_observation(&mut host,request,|_|Ok(())).unwrap();assert_eq!(actual_fixture_files(&root),before);
}
#[test]fn actual_all12_generation_check_observation_catches_changed_output_absence_and_recovers_without_overwrite(){
 let(root,_cache,request)=fixture("all12-observation-target-negative",false);let target=root.join("code/engine/_generated/deps.dm");let mut host=BuildHost::default();let mut calls=0;let error=dmbc::with_all_generation_check_input_observation(&mut host,request.clone(),|_|{calls+=1;fs::write(&target,b"external output\n")?;Ok(())}).unwrap_err();assert_eq!(calls,1);assert_eq!(fs::read(&target).unwrap(),b"external output\n");assert!(!error.to_string().is_empty());fs::remove_file(&target).unwrap();dmbc::with_all_generation_check_input_observation(&mut host,request,|_|Ok(())).unwrap();assert!(!target.exists());
}
#[test]fn actual_all12_generation_check_observation_exact_target_bytes_refuse_same_stamp_mutation(){
 let(root,_cache,request)=fixture("all12-observation-target-bytes",false);let target=root.join("code/engine/_generated/deps.dm");let before=b"existing target\n";fs::write(&target,before).unwrap();let modified=fs::metadata(&target).unwrap().modified().unwrap();let mut host=BuildHost::default();let error=dmbc::with_all_generation_check_input_observation(&mut host,request.clone(),|_|{fs::write(&target,b"external target\n")?;let file=fs::OpenOptions::new().write(true).open(&target)?;file.set_times(fs::FileTimes::new().set_modified(modified))?;drop(file);Ok(())}).unwrap_err();assert_eq!(fs::read(&target).unwrap(),b"external target\n");assert!(!error.to_string().is_empty());fs::write(&target,before).unwrap();dmbc::with_all_generation_check_input_observation(&mut host,request,|_|Ok(())).unwrap();assert_eq!(fs::read(&target).unwrap(),before);
}
#[test]fn actual_all12_generation_check_observation_rejects_missing_role_and_real_quota_then_recovers(){
 let(root,_cache,mut request)=fixture("all12-observation-all-role-quota",false);let before=actual_fixture_files(&root);let mut host=BuildHost::default();let full=request.clone();request.policy_inputs.as_mut().unwrap().workspace_generators.pop();let mut calls=0;assert!(dmbc::with_all_generation_check_input_observation(&mut host,request,|_|{calls+=1;Ok(())}).is_err());assert_eq!(calls,0);assert_eq!(actual_fixture_files(&root),before);let limit=host.source_arena_work().transformed_source_address_limit().unwrap();let pressure=host.source_arena_work().reserve(limit-512*1024).unwrap();let error=dmbc::with_all_generation_check_input_observation(&mut host,full.clone(),|_|{calls+=1;Ok(())}).unwrap_err();assert_eq!(actual_io(error.as_ref()).unwrap().kind(),io::ErrorKind::OutOfMemory);assert_eq!(calls,0);drop(pressure);dmbc::with_all_generation_check_input_observation(&mut host,full,|_|Ok(())).unwrap();assert_eq!(actual_fixture_files(&root),before);
}

#[test]fn actual_all12_generation_check_observation_retains_first_export_io_even_if_callback_catches_it(){
 struct Stop;impl io::Write for Stop{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{panic!("no later flush after actual first error")}}
 let(root,_cache,request)=fixture("all12-observation-export-first-io",false);let before=actual_fixture_files(&root);let mut host=BuildHost::default();let error=dmbc::with_all_generation_check_input_observation(&mut host,request,|mut observation|{assert!(observation.write_header(&mut Stop).is_err());assert!(observation.write_report(&mut Stop).is_err());Ok(())}).unwrap_err();assert_eq!(actual_io(error.as_ref()).unwrap().raw_os_error(),Some(1450));assert_eq!(actual_fixture_files(&root),before);
}
